document.addEventListener("DOMContentLoaded", function () {
    var elements = document.querySelectorAll('.alg-wc-wl-btn');
    elements.forEach(function (element) {
        var span = element.nextElementSibling;
        // Перевірка, чи наступний елемент після кнопки є <span>
        if (span && span.tagName.toLowerCase() === 'span') {
            if (element.classList.contains('remove')) {
                span.textContent = 'Видалити з листа бажань';
            } else {
                span.textContent = 'Додати до листа бажань';
            }

            element.addEventListener('click', function () {
                toggleFavorite(this);
            });
        }
    });

});

function toggleFavorite(element) {
    var span = element.nextElementSibling;
    if (element.classList.contains('add')) {
        element.classList.remove('add');
        element.classList.add('remove');
        span.textContent = 'Видалити з листа бажань';
    } else {
        element.classList.remove('remove');
        element.classList.add('add');
        span.textContent = 'Додати до листа бажань';
    }
}
