$(document).mouseup(function (e) {

	let container = $('.login-call__content');

	if ($('.login-call').hasClass('_active')) {

		if (!$("a").is(e.target)
			&& !container.is(e.target)
			&& container.has(e.target).length === 0) {

			$('.login-call__close').trigger('click');
		}
	}
});

