document.addEventListener("DOMContentLoaded", function() {
    // Знаходимо елемент <body>
    let bodyElement = document.querySelector('body');

    // Перевіряємо, чи в елементі <body> є клас 'paged'
    if (bodyElement.classList.contains('paged')) {
        // Нічого не робимо, оскільки клас 'paged' присутній
    } else {
        // Знаходимо мета-тег за його ім'ям
        let metaTag = document.querySelector('meta[name="robots"]');

        // Перевіряємо, чи мета-тег існує перед тим, як його видалити
        if (metaTag) {
            // Видаляємо мета-тег
            metaTag.parentNode.removeChild(metaTag);
        }
    }
    if (window.location.pathname.includes('/cart')) {
        // Створюємо новий мета-тег
        var metaTag = document.createElement('meta');
        metaTag.name = 'robots';
        metaTag.content = 'noindex, follow';

        // Додаємо мета-тег до <head>
        document.head.appendChild(metaTag);
    }
    if (bodyElement && bodyElement.classList.contains('search')) {
        // Створюємо новий мета-тег
        let metaTag = document.createElement('meta');
        metaTag.name = 'robots';
        metaTag.content = 'noindex, follow';

        // Додаємо мета-тег до <head>
        document.head.appendChild(metaTag);
    }
});

document.addEventListener("DOMContentLoaded", function() {
	function adjustMainMargin() {
            var header = document.querySelector("header");
            var main = document.querySelector("main");

            if (header && main) {
                var headerRect = header.getBoundingClientRect();
                var headerComputedStyle = window.getComputedStyle(header);
                var headerHeight = headerRect.height;
                var paddingTop = parseFloat(headerComputedStyle.paddingTop);
                var paddingBottom = parseFloat(headerComputedStyle.paddingBottom);
                var marginTop = parseFloat(headerComputedStyle.marginTop);
                var marginBottom = parseFloat(headerComputedStyle.marginBottom);         

                // Якщо потрібно врахувати padding або margin
                headerHeight = headerHeight + paddingTop + paddingBottom + marginTop + marginBottom;

                main.style.marginTop = headerHeight + "px";
            }
        }

        document.addEventListener("DOMContentLoaded", function() {
            // Викликаємо adjustMainMargin з більшою затримкою
            setTimeout(adjustMainMargin, 500);
        });

        // Опціонально: викликати функцію при зміні розміру вікна
        window.addEventListener("resize", adjustMainMargin);
});

